# This is greedy player which reads/replays same inputs
# as generated by endgame_gen.

import argparse

import json
import noisy_mm

from greedy_player import posterior
from pathlib import Path

def main():
    parser = argparse.ArgumentParser(usage="Re-run all samples_unique results and cat filtered data.")
    parser.add_argument("--temp", type=float, default=0.0)
    parser.add_argument("--p_corr", type=float, default=0.2, help="probability of each digit corruption")
    parser.add_argument("--min-length", "-l", type=int)
    args = parser.parse_args()
    files = sorted(Path("samples_unique").glob("*.json"))
    for f in files:
        with open(f, 'r') as file:
            sample = json.load(file)

        history = []
        for turn in sample['turns'][:-1]:
            [b, w] = turn['reply'].split()
            history.append((turn['guess'], int(b), int(w)))
        
        belief = list(posterior(noisy_mm.DATASET, history, args.p_corr).items())
        probs = list(reversed(sorted([p for _, p in belief])))

        if len(probs) > 1:
            rate = f"{probs[0]:.3}/{probs[1]:.3} = {probs[0]/probs[1]:.3}"
        else:
            rate = "n/a"

        if args.min_length is None or len(probs) >= args.min_length:
            print(f"{len(probs)} {f} ... {rate}")


if __name__ == '__main__':
    main()
